{
  "info": {
    "path": "/Volumes/EXTERNAL/自媒体/AI博主1000视频研究-20261007/V2本地读取/media/7637698039943089462.mp4",
    "source": "/Volumes/EXTERNAL/自媒体/AI博主1000视频研究-20261007/V2本地读取/media/7637698039943089462.mp4",
    "sourceKind": "local",
